    {"slug":"stripe-fee","title":"Stripe Fee Calculator","desc":"Calculate net revenue after Stripe processing fees. Free for online businesses.","fields":[{"id":"price","label":"Transaction Amount","placeholder":"100.00","prefix":"$"},{"id":"fee","label":"Stripe Fee Rate (%)","placeholder":"2.9","suffix":"%"},{"id":"cost","label":"Fixed Fee","placeholder":"0.30","prefix":"$"},{"id":"shipping","label":"","placeholder":"","prefix":"","suffix":""},{"id":"ads","label":"","placeholder":"","prefix":"","suffix":""}],"results":[{"id":"profit","label":"Net After Fees","prefix":"$"},{"id":"margin","label":"Fee Amount","prefix":"$"},{"id":"roi","label":"Effective Rate","prefix":"%"}],"calc_js":"var price=getVal('price'),fee=getVal('fee'),fixed=getVal('cost');var feeAmt=price*(fee/100)+fixed;var net=price-feeAmt;var eff=(feeAmt/price*100);document.getElementById('profit').innerText='$'+net.toFixed(2);document.getElementById('margin').innerText='$'+feeAmt.toFixed(2);document.getElementById('roi').innerText=eff.toFixed(2)+'%';"},
