    {"slug":"wholesale","title":"Wholesale Profit Calculator","desc":"Calculate wholesale profits with bulk pricing and volume discounts.","fields":[{"id":"price","label":"Wholesale Price per Unit","placeholder":"8.00","prefix":"$"},{"id":"cost","label":"Unit Cost","placeholder":"3.00","prefix":"$"},{"id":"shipping","label":"Shipping per Unit","placeholder":"0.50","prefix":"$"},{"id":"fee","label":"Platform Fee (%)","placeholder":"3","suffix":"%"},{"id":"ads","label":"Storage/Handling","placeholder":"0.25","prefix":"$"}],"results":[{"id":"profit","label":"Net Profit/Unit","prefix":"$"},{"id":"margin","label":"Profit Margin","prefix":""},{"id":"roi","label":"ROI","prefix":""}],"calc_js":PROFIT_CALC_JS},
    {"slug":"retail-markup","title":"Retail Markup Calculator","desc":"Calculate retail price, markup percentage, and gross profit margin.","fields":[{"id":"cost","label":"Wholesale Cost","placeholder":"20.00","prefix":"$"},{"id":"price","label":"Retail Price","placeholder":"50.00","prefix":"$"},{"id":"shipping","label":"","placeholder":"","prefix":"","suffix":""},{"id":"fee","label":"","placeholder":"","prefix":"","suffix":""},{"id":"ads","label":"","placeholder":"","prefix":"","suffix":""}],"results":[{"id":"profit","label":"Gross Profit","prefix":"$"},{"id":"margin","label":"Margin %","prefix":""},{"id":"roi","label":"Markup %","prefix":"%"}],"calc_js":"var cost=getVal('cost'),price=getVal('price');var profit=price-cost;var margin=cost>0?(profit/price*100):0;var markup=cost>0?((price-cost)/cost*100):0;document.getElementById('profit').innerText='$'+profit.toFixed(2);document.getElementById('margin').innerText=margin.toFixed(1)+'%';document.getElementById('roi').innerText=markup.toFixed(1)+'%';"},
    {"slug":"crypto-trading","title":"Crypto Trading Profit Calculator","desc":"Calculate crypto trading profits including exchange fees and slippage.","fields":[{"id":"price","label":"Sell Price","placeholder":"50000","prefix":"$"},{"id":"cost","label":"Buy Price","placeholder":"48000","prefix":"$"},{"id":"shipping","label":"Investment Amount","placeholder":"1000","prefix":"$"},{"id":"fee","label":"Exchange Fee (%)","placeholder":"0.5","suffix":"%"},{"id":"ads","label":"Gas/Network Fee","placeholder":"5","prefix":"$"}],"results":[{"id":"profit","label":"Net Profit","prefix":"$"},{"id":"margin","label":"Return %","prefix":""},{"id":"roi","label":"ROI","prefix":""}],"calc_js":PROFIT_CALC_JS},
    {"slug":"freelance-rate","title":"Freelance Rate Calculator","desc":"Calculate your freelance hourly rate based on desired income and expenses.","fields":[{"id":"price","label":"Desired Annual Income","placeholder":"100000","prefix":"$"},{"id":"cost","label":"Annual Expenses","placeholder":"20000","prefix":"$"},{"id":"shipping","label":"Billable Hours/Year","placeholder":"1500","prefix":""},{"id":"fee","label":"Tax Rate (%)","placeholder":"25","suffix":"%"},{"id":"ads","label":"Benefits/Insurance","placeholder":"10000","prefix":"$"}],"results":[{"id":"profit","label":"Hourly Rate","prefix":"$"},{"id":"margin","label":"Monthly Target","prefix":"$"},{"id":"roi","label":"Take-home","prefix":"$"}],"calc_js":"var income=getVal('price'),exp=getVal('cost'),hours=getVal('shipping'),tax=getVal('fee')/100,benefits=getVal('ads');var needed=income+exp;var gross=needed/(1-tax);var hourly=gross/max(hours,1);var monthly=gross/12;var net=income;document.getElementById('profit').innerText='$'+hourly.toFixed(2);document.getElementById('margin').innerText='$'+monthly.toFixed(0);document.getElementById('roi').innerText='$'+net.toFixed(0);"},
    {"slug":"restaurant","title":"Restaurant Profit Calculator","desc":"Calculate food cost percentage and dish profitability for restaurants.","fields":[{"id":"price","label":"Menu Price","placeholder":"18.00","prefix":"$"},{"id":"cost","label":"Ingredient Cost","placeholder":"5.00","prefix":"$"},{"id":"shipping","label":"Labor per Dish","placeholder":"3.00","prefix":"$"},{"id":"fee","label":"Overhead (%)","placeholder":"30","suffix":"%"},{"id":"ads","label":"Delivery Commission","placeholder":"0","prefix":"$"}],"results":[{"id":"profit","label":"Dish Profit","prefix":"$"},{"id":"margin","label":"Profit Margin","prefix":""},{"id":"roi","label":"Food Cost %","prefix":"%"}],"calc_js":"var price=getVal('price'),cost=getVal('cost'),labor=getVal('shipping'),fee=getVal('fee')/100,ads=getVal('ads');var overhead=price*fee;var total=cost+labor+overhead+ads;var profit=price-total;var margin=price>0?(profit/price*100):0;var foodCost=cost/price*100;document.getElementById('profit').innerText='$'+profit.toFixed(2);document.getElementById('margin').innerText=margin.toFixed(1)+'%';document.getElementById('roi').innerText=foodCost.toFixed(1)+'%';"},
    {"slug":"real-estate","title":"Real Estate Profit Calculator","desc":"Calculate property investment profits including closing costs and agent fees.","fields":[{"id":"price","label":"Sale Price","placeholder":"350000","prefix":"$"},{"id":"cost","label":"Purchase Price","placeholder":"280000","prefix":"$"},{"id":"shipping","label":"Renovation Cost","placeholder":"30000","prefix":"$"},{"id":"fee","label":"Agent Fee (%)","placeholder":"6","suffix":"%"},{"id":"ads","label":"Closing/Holding Costs","placeholder":"5000","prefix":"$"}],"results":[{"id":"profit","label":"Net Profit","prefix":"$"},{"id":"margin","label":"ROI %","prefix":""},{"id":"roi","label":"Total Invested","prefix":"$"}],"calc_js":PROFIT_CALC_JS},
    {"slug":"break-even","title":"Break Even Calculator","desc":"Calculate break-even point in units and sales dollars.","fields":[{"id":"cost","label":"Fixed Costs","placeholder":"5000","prefix":"$"},{"id":"price","label":"Price per Unit","placeholder":"50","prefix":"$"},{"id":"shipping","label":"Variable Cost/Unit","placeholder":"20","prefix":"$"},{"id":"fee","label":"","placeholder":"","prefix":"","suffix":""},{"id":"ads","label":"","placeholder":"","prefix":"","suffix":""}],"results":[{"id":"profit","label":"Break-Even Units","prefix":""},{"id":"margin","label":"Break-Even Revenue","prefix":"$"},{"id":"roi","label":"Contrib Margin","prefix":"$"}],"calc_js":"var fixed=getVal('cost'),price=getVal('price'),vc=getVal('shipping');var cm=price-vc;var be_units=cm>0?Math.ceil(fixed/cm):0;var be_rev=be_units*price;document.getElementById('profit').innerText=be_units;document.getElementById('margin').innerText='$'+be_rev.toFixed(0);document.getElementById('roi').innerText='$'+cm.toFixed(2);"},
    {"slug":"facebook-ads","title":"Facebook Ads Profit Calculator","desc":"Calculate Facebook ad campaign ROI and profit. For dropshippers and eCommerce.","fields":[{"id":"price","label":"Revenue from Ads","placeholder":"5000","prefix":"$"},{"id":"cost","label":"Product Cost","placeholder":"2000","prefix":"$"},{"id":"shipping","label":"Ad Spend","placeholder":"1000","prefix":"$"},{"id":"fee","label":"Platform Fee (%)","placeholder":"5","suffix":"%"},{"id":"ads","label":"Creative/VA Cost","placeholder":"200","prefix":"$"}],"results":[{"id":"profit","label":"Net Profit","prefix":"$"},{"id":"margin","label":"ROAS","prefix":"x"},{"id":"roi","label":"ROI","prefix":""}],"calc_js":"var rev=getVal('price'),cost=getVal('cost'),adspend=getVal('shipping'),fee=getVal('fee')/100,extra=getVal('ads');var feeAmt=rev*fee;var total=cost+adspend+feeAmt+extra;var profit=rev-total;var roas=adspend>0?rev/adspend:0;var roi=total>0?(profit/total*100):0;document.getElementById('profit').innerText='$'+profit.toFixed(2);document.getElementById('margin').innerText=roas.toFixed(1)+'x';document.getElementById('roi').innerText=roi.toFixed(1)+'%';"},
    {"slug":"google-ads","title":"Google Ads Profit Calculator","desc":"Calculate Google Ads ROI and profit per campaign.","fields":[{"id":"price","label":"Campaign Revenue","placeholder":"10000","prefix":"$"},{"id":"cost","label":"Product/Service Cost","placeholder":"4000","prefix":"$"},{"id":"shipping","label":"Ad Spend","placeholder":"2000","prefix":"$"},{"id":"fee","label":"Management Fee (%)","placeholder":"10","suffix":"%"},{"id":"ads","label":"Landing Page/Tools","placeholder":"300","prefix":"$"}],"results":[{"id":"profit","label":"Net Profit","prefix":"$"},{"id":"margin","label":"ROAS","prefix":"x"},{"id":"roi","label":"ROI","prefix":""}],"calc_js":"var rev=getVal('price'),cost=getVal('cost'),adspend=getVal('shipping'),fee=getVal('fee')/100,extra=getVal('ads');var total=cost+adspend+rev*fee+extra;var profit=rev-total;var roas=adspend>0?rev/adspend:0;var roi=total>0?(profit/total*100):0;document.getElementById('profit').innerText='$'+profit.toFixed(2);document.getElementById('margin').innerText=roas.toFixed(1)+'x';document.getElementById('roi').innerText=roi.toFixed(1)+'%';"},
    {"slug":"tiktok-ads","title":"TikTok Ads Profit Calculator","desc":"Calculate TikTok ad campaign ROI for dropshipping and eCommerce.","fields":[{"id":"price","label":"Revenue from Ads","placeholder":"3000","prefix":"$"},{"id":"cost","label":"Product Cost","placeholder":"1200","prefix":"$"},{"id":"shipping","label":"Ad Spend","placeholder":"800","prefix":"$"},{"id":"fee","label":"TikTok Fee (%)","placeholder":"2","suffix":"%"},{"id":"ads","label":"Content Creation","placeholder":"200","prefix":"$"}],"results":[{"id":"profit","label":"Net Profit","prefix":"$"},{"id":"margin","label":"ROAS","prefix":"x"},{"id":"roi","label":"ROI","prefix":""}],"calc_js":"var rev=getVal('price'),cost=getVal('cost'),adspend=getVal('shipping'),fee=getVal('fee')/100,extra=getVal('ads');var total=cost+adspend+rev*fee+extra;var profit=rev-total;var roas=adspend>0?rev/adspend:0;var roi=total>0?(profit/total*100):0;document.getElementById('profit').innerText='$'+profit.toFixed(2);document.getElementById('margin').innerText=roas.toFixed(1)+'x';document.getElementById('roi').innerText=roi.toFixed(1)+'%';"},
